"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["48258"],{21596(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>a,contentTitle:()=>r,toc:()=>u,assets:()=>h});var o=JSON.parse('{"id":"tianya/luxunposition","title":"","description":"It happened to be lunchtime with nothing to do, and seeing the recent hot topic of using Lu Xun to make points, this lady joins the fun to say a few words about him. Actually this lady has no interest in Lu Xun, although I once wrote a regulated verse about him: \\"Hung the medicine pot to save dead souls in vain, angrily turned pen-blade to wake the nation\'s stupor. Wild fields wandering, feeling the flower-cap\'s fate; hometown mourning the past, calling a new era. One person unforgiving -- that is true forgiveness; ten thousand things hard to say -- yet finally words of indignation. The catastrophic waves not ended, the brothers ended; spirit banners compete to hang at the gates of the illusory city.\\" I also wrote a post \\"From a purely literary standpoint, ten thousand Zhou Shurens couldn\'t match one Zhou Zuoren.\\" But this lady truly has no interest in Lu Xun, just as this lady has no interest in his foot-washing.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/luxunposition.md","sourceDirName":"tianya","slug":"/tianya/luxunposition","permalink":"/en/tianya/luxunposition","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"luxunposition","title":"","hide_table_of_contents":true,"sidebar_label":"Regardless of what Lu Xun was, when invoking Lu Xun, one\'s stance need not align with his!"},"sidebar":"tianyaSidebar","previous":{"title":"Men \u2014 whether they have the goods or not, they\'re no good!","permalink":"/en/tianya/mennothing"},"next":{"title":"Of those who curse Confucianism all day, how many truly understand it? Go back and study properly \u2014 stop embarrassing yourselves","permalink":"/en/tianya/gobacktoschool"}}'),i=n(74848),s=n(28453);let a={id:"luxunposition",title:"",hide_table_of_contents:!0,sidebar_label:"Regardless of what Lu Xun was, when invoking Lu Xun, one's stance need not align with his!"},r="Regardless of What Lu Xun Is, Using Lu Xun to Make a Point Doesn't Mean Your Position Has to Align with Lu Xun's!",h={},u=[];function l(e){let t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"regardless-of-what-lu-xun-is-using-lu-xun-to-make-a-point-doesnt-mean-your-position-has-to-align-with-lu-xuns",children:"Regardless of What Lu Xun Is, Using Lu Xun to Make a Point Doesn't Mean Your Position Has to Align with Lu Xun's!"})}),"\n",(0,i.jsx)(t.p,{children:'It happened to be lunchtime with nothing to do, and seeing the recent hot topic of using Lu Xun to make points, this lady joins the fun to say a few words about him. Actually this lady has no interest in Lu Xun, although I once wrote a regulated verse about him: "Hung the medicine pot to save dead souls in vain, angrily turned pen-blade to wake the nation\'s stupor. Wild fields wandering, feeling the flower-cap\'s fate; hometown mourning the past, calling a new era. One person unforgiving -- that is true forgiveness; ten thousand things hard to say -- yet finally words of indignation. The catastrophic waves not ended, the brothers ended; spirit banners compete to hang at the gates of the illusory city." I also wrote a post "From a purely literary standpoint, ten thousand Zhou Shurens couldn\'t match one Zhou Zuoren." But this lady truly has no interest in Lu Xun, just as this lady has no interest in his foot-washing.'}),"\n",(0,i.jsx)(t.p,{children:"But regardless of what Lu Xun is, using Lu Xun to make a point doesn't mean your position has to align with Lu Xun's! Not just with Lu Xun -- using anyone to make a point requires no alignment with their position. Like a chef making soup with a chicken: obviously he needn't align with the chicken's position, otherwise he might as well boil himself. A doctor dissecting a corpse naturally needn't adopt the corpse's position. A historian who adopted the position of every research subject would make historical research entirely meaningless. For scientific research, the only position is the objective one -- even if absolute objectivity is a myth, there is no other choice."}),"\n",(0,i.jsx)(t.p,{children:"Of course, making a point isn't necessarily research. But if even research, something so rigorous, needn't share the research subject's position, then making casual points is even less required. Everything is ultimately just making points -- even the ultimate purpose of research is to make points, otherwise nobody would need to make any points. Otherwise, when you discuss Wang Jingwei you'd have to take his position, when discussing Chiang Kai-shek his position, when discussing Mao Zedong his position -- that would be more exhausting than a chameleon."}),"\n",(0,i.jsx)(t.p,{children:"Actually, whether you take a position or not doesn't matter. The key is understanding this: everyone only makes points from their own position. Don't bluff about truth -- even the world you see is only the world you see, even your hearing stands on the position of your own ears. Apart from bluffing on behalf of yourself, who else can you represent? When you criticize others, you're also just standing on your own position. Those who try to conceal this are merely self-gratifying hypocrites -- and leftists love playing this role most."})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var o=n(96540);let i={},s=o.createContext(i);function a(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);